      "rationale": "One objective requires profile discovery, comparisons across several reservations, a policy decision, and handling the documented follow-up; the calls are not counted as fixed effort units.",
      "evidence": [{"citation_id": "E0123"}, {"citation_id": "E0124"}, {"citation_id": "E0122"}]
    },
    "reasoning": {
      "level": 3,
      "rationale": "The agent must distinguish the claimed cancellation and cabin from the actual booked itinerary, then apply both eligibility and permitted-reason rules despite insistence.",
      "evidence": [{"citation_id": "E0003"}, {"citation_id": "E0117"}, {"citation_id": "E0118"}, {"citation_id": "E0120"}]
    },
    "tool_use": {
      "level": 2,
      "rationale": "The intended reads bind a known user ID and profile-derived reservation IDs to simple lookup arguments; a supervisor request adds a separate transfer tool, not complex arguments.",
