      "levels": {"reasoning": 2, "tool_use": 1, "information": 2}
    },
    {
      "unit_id": "reference_002",
      "applicability_rationale": "Details of 59XX6W are needed to assess its separate cancellation basis.",
      "evidence": [{"citation_id": "E0138"}, {"citation_id": "E0275"}],
      "rationale": "A direct lookup establishes the reservation's economy cabin and insurance status for the illness-related request.",
      "applicability": "required",
      "levels": {"reasoning": 2, "tool_use": 1, "information": 2}
    },
    {
      "unit_id": "reference_003",
      "applicability_rationale": "XEHM4B is basic economy, so the requested business upgrade is on the intended path.",
